#include <iostream>
#include <memory>
struct S {
    S() { std::cout << "make\n"; }
    ~S() { std::cout << "kill\n"; }
};
int main() {
    auto p = std::make_unique<S>();
    auto q = std::move(p);
    std::cout << (p == nullptr) << (q != nullptr) << "\n";
    q.reset();
    std::cout << "end\n";
}

#include <iostream>
#include <memory>
struct S { ~S() { std::cout << "~S"; } };
int main() {
    auto p = std::make_unique<S>();
    S* raw = p.release();
    std::cout << (p == nullptr);
    delete raw;
}
